        while True:
            move_column = int(input(f"{self.turn} enter a column: "))
            move_row = int(input(f"{self.turn} enter a row: "))
            if self.board[move_row][move_column] == "_":
                self.board[move_row][move_column] = self.turn
                return True
            else:
                print("This position is already taken")

    def game_over(self):
        # Check for winner
        for player in [self.player1, self.player2]:
            # check for columns
            for col in range(self.board_size):
                if self.board[0][col] == self.board[1][col] == self.board[2][col] == player:
                    return True

            # check for rows
            for row in range(self.board_size):
                if self.board[row] == [player, player, player]:           
