  for i in range(BOARD_SIZE):
    for j in range(BOARD_SIZE):
      if board[i,j] == PLAYER:
        print('X ', end="")
      elif board[i,j] == AI:
        print('O ', end="")
      else:
        print('  ', end="")
    print()

